-- Import des courriers arrivées 2019
-- Source : 2019.xlsx (feuille 2019).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N°                -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE CREATION     -> dt_datearrivee
--   N° ET DATE DE COR -> txt_reference, txt_numcourier et dt_datecourier
--   PRENOMS + NOMS    -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS      -> txt_objet (libellé d'origine)
--   DESIGNATIONS      -> txt_designation (liste designationsParCategorie)
--   designation retenue -> txt_categorie
--   N° TITRES         -> txt_numTitreFoncier
--   ANCIEN TF         -> txt_numTitreMere
--   N° LOT            -> txt_numLot
--   SUPERFICIE        -> txt_superficie
--   SITUATION/LOTISSEMENT -> txt_lotissement
--   AGENTS TRAITEUR   -> txt_agenttraiteur
--   OBSERVATIONS      -> txt_observation
--   ETAT DES DOSSIERS -> ajouté à txt_observation
--   DATE DEPART       -> ajoutée à txt_observation
--   correspondance absente -> référence « <N° arrivée> du jj-mm-aaaa »
--   NICAD cité dans l'objet -> txt_NICAD
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates d'arrivée illisibles reconstituées sur la ligne voisine : 6
-- Numéros d'arrivée reconstitués entre deux numéros voisins : 0
-- Lignes importées : 1908
-- Lignes non importées :
--   ligne Excel 914 : N° 752 sans objet, nom ni titre
--   ligne Excel 1444 : N° 1213 sans objet, nom ni titre
--
-- Répartition des catégories :
--    1649  Demande SERVICES
--     176  Information
--      59  Réquisition - Instruction
--      20  Convocation - Invitation
--       4  Réclamation - Signalement
-- Désignations :
--     770  Morcellements
--     361  Demande de Cession définitive
--     165  Demande de Régularisation par voie de Bail
--     145  Demande de situation foncière
--     122  Transmission lettre
--      59  Instruction à suivre
--      52  Demande de délimitation
--      38  Demande d'états des lieux
--      28  Autres
--      25  Demande de terrain/Echange
--      21  Autorisation de lotir
--      21  Tribunal
--      20  Demande d'extraits de plan
--      12  Réunion
--       7  Formation
--       6  Note de service
--       6  Réquisition d'immatriculation
--       6  Lettre
--       5  Réceptions de lotissements
--       5  Demande d'évaluation
--       5  Décision - Arrêté
--       4  Demande d'attestation du Cadastre
--       4  Plainte
--       4  Demande de Titre foncier
--       3  Document administratif
--       3  PV - Compte - rendu
--       2  Litiges
--       2  Circulaire
--       1  Rencontre
--       1  Duplication de CIC
--       1  Réquisition DSCOS
--       1  Rapport
--       1  Demande de reconstruction
--       1  Autorisation de construction
--       1  Demande de CIC

SET NAMES utf8mb4;

-- Certains N° TF du classeur dépassent 25 caractères (listes de titres).
ALTER TABLE `arrivees`
  MODIFY `txt_numTitreFoncier` VARCHAR(255) NULL,
  MODIFY `txt_numTitreMere` VARCHAR(255) NULL,
  MODIFY `txt_objet` VARCHAR(400) NOT NULL;

START TRANSACTION;






COMMIT;
